<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class CanteenRecipeController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('canteen_manager')||$r->user()->canDo('canteen.manage'),403);}
public function index(Request $r){$this->manage($r);$recipes=DB::table('canteen_recipes')->orderBy('name')->get();$products=DB::table('canteen_products')->where('active',1)->orderBy('name')->get();return view('canteen.recipes',compact('recipes','products'));}
public function store(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','yield_portions'=>'required|numeric|min:0.01','technology'=>'nullable|string|max:10000','energy_kcal'=>'nullable|numeric|min:0','protein_g'=>'nullable|numeric|min:0','fat_g'=>'nullable|numeric|min:0','carb_g'=>'nullable|numeric|min:0']);DB::table('canteen_recipes')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function item(Request $r,$recipe){$this->manage($r);$d=$r->validate(['canteen_product_id'=>'required|exists:canteen_products,id','quantity'=>'required|numeric|min:0.001']);DB::table('canteen_recipe_items')->updateOrInsert(['canteen_recipe_id'=>$recipe,'canteen_product_id'=>$d['canteen_product_id']],['quantity'=>$d['quantity'],'updated_at'=>now(),'created_at'=>now()]);return back();}
public function forecast(Request $r){$this->manage($r);$date=$r->get('date',date('Y-m-d',strtotime('+1 day')));$menus=DB::table('meal_menus as m')->leftJoin('canteen_recipes as r','r.id','=','m.canteen_recipe_id')->where(['m.menu_date'=>$date,'m.active'=>1])->select('m.*','r.name recipe_name','r.yield_portions')->get();$need=[];foreach($menus as $m){$orders=DB::table('meal_preorders')->where(['meal_menu_id'=>$m->id,'status'=>'ordered'])->count();$portions=max($orders,(int)($m->planned_portions??0));if(!$m->canteen_recipe_id)continue;foreach(DB::table('canteen_recipe_items as i')->join('canteen_products as p','p.id','=','i.canteen_product_id')->where('i.canteen_recipe_id',$m->canteen_recipe_id)->select('i.*','p.name','p.unit')->get() as $i){$q=(float)$i->quantity*$portions/(float)$m->yield_portions;if(!isset($need[$i->canteen_product_id]))$need[$i->canteen_product_id]=['name'=>$i->name,'unit'=>$i->unit,'required'=>0];$need[$i->canteen_product_id]['required']+=$q;}}foreach($need as $id=>&$n)$n['stock']=(float)DB::table('canteen_stock_batches')->where('canteen_product_id',$id)->sum('quantity_remaining');return view('canteen.forecast',compact('date','menus','need'));}
}
class CanteenStudentController extends Controller{
private function sid(Request $r){abort_unless($r->user()->student_id,403);return $r->user()->student_id;}
public function index(Request $r){$sid=$this->sid($r);$today=date('Y-m-d');$assignment=DB::table('student_meal_assignments as a')->join('meal_categories as c','c.id','=','a.meal_category_id')->where('a.student_id',$sid)->where('a.valid_from','<=',$today)->where(function($q)use($today){$q->whereNull('a.valid_to')->orWhere('a.valid_to','>=',$today);})->select('a.*','c.name category_name')->orderByDesc('a.valid_from')->first();$pass=DB::table('student_meal_passes')->where(['student_id'=>$sid,'status'=>'active'])->first();if(!$pass&&$assignment){$token=Str::random(56);$id=DB::table('student_meal_passes')->insertGetId(['student_id'=>$sid,'token'=>$token,'status'=>'active','issued_at'=>now(),'issued_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$pass=DB::table('student_meal_passes')->find($id);}$menus=DB::table('meal_menus')->whereBetween('menu_date',[$today,date('Y-m-d',strtotime('+7 days'))])->where('active',1)->orderBy('menu_date')->get();$orders=DB::table('meal_preorders')->where('student_id',$sid)->where('meal_date','>=',$today)->pluck('status','meal_menu_id');$issues=DB::table('meal_issues')->where('student_id',$sid)->orderByDesc('issued_at')->limit(20)->get();return view('canteen.student',compact('assignment','pass','menus','orders','issues'));}
public function preorder(Request $r,$menu){$sid=$this->sid($r);$m=DB::table('meal_menus')->find($menu);abort_if(!$m||$m->menu_date<date('Y-m-d'),404);DB::table('meal_preorders')->updateOrInsert(['student_id'=>$sid,'meal_menu_id'=>$menu],['meal_date'=>$m->menu_date,'status'=>'ordered','updated_at'=>now(),'created_at'=>now()]);return back();}
public function cancel(Request $r,$menu){$sid=$this->sid($r);DB::table('meal_preorders')->where(['student_id'=>$sid,'meal_menu_id'=>$menu])->where('meal_date','>',date('Y-m-d'))->update(['status'=>'cancelled','updated_at'=>now()]);return back();}
}